import numpy as np
from collections import defaultdict
from typing import List, Dict, Any, Tuple

class CommunicatingTeamAgent:
    def __init__(self, agent_id: str, all_agent_ids: List[str], learning_rate: float = 0.1, epsilon: float = 0.1):
        self.agent_id = agent_id
        self.all_agent_ids = all_agent_ids
        self.total_reward = 0
        self.learning_rate = learning_rate
        self.epsilon = epsilon

        self.possible_teams = ['Team A', 'Team B']

        # Agent's strategy for choosing a team (how good is this team choice for me?)
        self.team_choice_strategy = {} 
        for team in self.possible_teams:
            self.team_choice_strategy[team] = {'success': 1, 'attempts': 2, 'value_est': 0.5}

        # Agent's strategy for *signaling* a team (learns which signal leads to better *collective* outcomes)
        self.signaling_strategy = {}
        for team in self.possible_teams:
            self.signaling_strategy[team] = {'success': 1, 'attempts': 2, 'value_est': 0.5} 

      # Agent's interpretation of observed signals: maps (sender_id, observed_signal) -> expected_team_a_prob
        self.signal_interpretation = defaultdict(lambda: {'expected_team_a_count': 1, 'observed_signals_count': 2, 'team_a_prob_est': 0.5})

        print(f"Communicating Team Agent {self.agent_id} initialized.")

    def choose_signal(self) -> str:
        """Chooses a signal (intended team) based on past effectiveness in achieving good outcomes."""
        if np.random.rand() < self.epsilon:
            return np.random.choice(self.possible_teams)
        else:
            return max(self.signaling_strategy, key=lambda s: self.signaling_strategy[s]['value_est'])

    def choose_final_team(self, observed_signals: Dict[str, str]) -> str:
        """
        Chooses a final team for the round, incorporating observed signals and a strong balancing bias.
        observed_signals: {agent_id: signal_string} for the current round
        """
        if np.random.rand() < self.epsilon:
            chosen_team = np.random.choice(self.possible_teams)
        else:
            action_values = {}
            # Base value from own learning for each team
            value_a = self.team_choice_strategy['Team A']['value_est']
            value_b = self.team_choice_strategy['Team B']['value_est']

            # Incorporate observed signals for *current round*
            num_signals_team_a = sum(1 for sid, signal in observed_signals.items() if signal == 'Team A')
            num_signals_team_b = sum(1 for sid, signal in observed_signals.items() if signal == 'Team B')

            # Stronger bias to balance teams based on current signals
            # If signals suggest imbalance, adjust own preference to counter it
            if num_signals_team_a > num_signals_team_b + 1:
                value_a -= 0.5 # Stronger penalty for perceived overcrowding
                value_b += 0.5 # Stronger boost for perceived undercrowding
            elif num_signals_team_b > num_signals_team_a + 1:
                value_b -= 0.5
                value_a += 0.5

            action_values['Team A'] = value_a
            action_values['Team B'] = value_b

            chosen_team = max(action_values, key=action_values.get)

        return chosen_team

    def update_learning(self, my_sent_signal: str, my_final_team_choice: str, my_reward: int, 
                        all_signals: Dict[str, str], all_final_choices: Dict[str, str]):
        """Updates agent's learning for signaling, team choice, and signal interpretation."""
        is_successful_round = my_reward > 0 

        # 1. Update primary team choice learning (how good was this team choice for my own reward)
        self.team_choice_strategy[my_final_team_choice]['attempts'] += 1
        if is_successful_round:
            self.team_choice_strategy[my_final_team_choice]['success'] += 1
        self.team_choice_strategy[my_final_team_choice]['value_est'] = \
            (1 - self.learning_rate) * self.team_choice_strategy[my_final_team_choice]['value_est'] + \
            self.learning_rate * (self.team_choice_strategy[my_final_team_choice]['success'] / self.team_choice_strategy[my_final_team_choice]['attempts'])

        # 2. Update signaling strategy learning (how effective was my signal in getting a good COLLECTIVE outcome)
        # For simplicity: if the round was collectively successful (balanced teams), my signal was effective.
        # We can use `is_successful_round` here as a proxy for good collective outcome for now.
        self.signaling_strategy[my_sent_signal]['attempts'] += 1
        if is_successful_round:
            self.signaling_strategy[my_sent_signal]['success'] += 1
        self.signaling_strategy[my_sent_signal]['value_est'] = \
            (1 - self.learning_rate) * self.signaling_strategy[my_sent_signal]['value_est'] + \
            self.learning_rate * (self.signaling_strategy[my_sent_signal]['success'] / self.signaling_strategy[my_sent_signal]['attempts'])

        # 3. Update signal interpretation (for all observed signals)
        for sender_id, signal in all_signals.items():
            if sender_id == self.agent_id: continue 

            # Observe what the sender *actually chose* after sending that signal
            sender_actual_choice = all_final_choices[sender_id]

            self.signal_interpretation[(sender_id, signal)]['observed_signals_count'] += 1
            if sender_actual_choice == 'Team A': 
                self.signal_interpretation[(sender_id, signal)]['expected_team_a_count'] += 1

            self.signal_interpretation[(sender_id, signal)]['team_a_prob_est'] = \
                (1 - self.learning_rate) * self.signal_interpretation[(sender_id, signal)]['team_a_prob_est'] + \
                self.learning_rate * (self.signal_interpretation[(sender_id, signal)]['expected_team_a_count'] / self.signal_interpretation[(sender_id, signal)]['observed_signals_count'])

        self.total_reward += my_reward

class TeamFormationEnvironment:
    def __init__(self, num_agents: int, reward_balanced_team: int = 5, penalty_imbalanced_team: int = -3):
        self.num_agents = num_agents
        self.reward_balanced_team = reward_balanced_team
        self.penalty_imbalanced_team = penalty_imbalanced_team
        print(f"Environment initialized for {num_agents} agents in Team Formation Game.")

    def resolve_round(self, agent_choices: Dict[str, str]) -> Tuple[Dict[str, int], int, int]:
        team_a_count = sum(1 for choice in agent_choices.values() if choice == 'Team A')
        team_b_count = sum(1 for choice in agent_choices.values() if choice == 'Team B')

        rewards = {}
        if abs(team_a_count - team_b_count) <= 1: 
            print(f"    Teams are balanced (A:{team_a_count}, B:{team_b_count}). All agents receive {self.reward_balanced_team} reward.")
            for agent_id in agent_choices.keys():
                rewards[agent_id] = self.reward_balanced_team
        else:
            print(f"    Teams are imbalanced (A:{team_a_count}, B:{team_b_count}). All agents receive {self.penalty_imbalanced_team} penalty.")
            for agent_id in agent_choices.keys():
                rewards[agent_id] = self.penalty_imbalanced_team

        return rewards, team_a_count, team_b_count # Also return counts for logging

# --- Simulation Setup ---
NUM_AGENTS = 5
NUM_ROUNDS = 70 # Increased rounds to allow communication and learning to converge

all_agent_ids = [f"Agent_{i+1}" for i in range(NUM_AGENTS)]

agents_dict = {}
for aid in all_agent_ids:
    agents_dict[aid] = CommunicatingTeamAgent(aid, all_agent_ids, learning_rate=0.2, epsilon=0.1)

env = TeamFormationEnvironment(NUM_AGENTS)

print(f"\n--- Starting {NUM_ROUNDS} Rounds of Multi-Agent Enhanced Team Formation Game with Communication ---")

for i in range(NUM_ROUNDS):
    # Phase 1: Agents choose and broadcast signals (intended team)
    current_signals = {} 
    for agent_id in all_agent_ids:
        current_signals[agent_id] = agents_dict[agent_id].choose_signal()

    # Phase 2: Agents choose final team based on observed signals
    current_final_choices = {} 
    for agent_id in all_agent_ids:
        observed_signals_by_others = {sid: signal for sid, signal in current_signals.items() if sid != agent_id}
        current_final_choices[agent_id] = agents_dict[agent_id].choose_final_team(observed_signals_by_others)

    # Phase 3: Environment Resolution
    rewards, team_a_count, team_b_count = env.resolve_round(current_final_choices)

    # Phase 4: Learning Update
    total_round_reward = 0
    for agent_id in all_agent_ids:
        agent = agents_dict[agent_id]
        agent_reward = rewards[agent_id]

        agent.update_learning(
            my_sent_signal=current_signals[agent_id],
            my_final_team_choice=current_final_choices[agent_id],
            my_reward=agent_reward,
            all_signals=current_signals, 
            all_final_choices=current_final_choices 
        )
        total_round_reward += agent_reward

    if (i + 1) % 10 == 0:
        print(f"\nRound {i+1} Summary (Teams: A:{team_a_count}, B:{team_b_count}, Collective Reward: {total_round_reward}):")
        for agent_id in all_agent_ids:
            agent = agents_dict[agent_id]
            print(f"  {agent.agent_id}: Total Reward = {agent.total_reward}")
            print(f"    Team Choice Est (A/B): {agent.team_choice_strategy['Team A']['value_est']:.2f}/{agent.team_choice_strategy['Team B']['value_est']:.2f}")
            print(f"    Signaling Est (A/B): {agent.signaling_strategy['Team A']['value_est']:.2f}/{agent.signaling_strategy['Team B']['value_est']:.2f}")
            for (sender_id, signal), data in agent.signal_interpretation.items():
                if sender_id != agent.agent_id:
                    print(f"    Interpretation {sender_id} sent {signal}: {data['team_a_prob_est']:.2f}")

print(f"\n--- Simulation Complete ---")
print("\nFinal Agent Rewards:")
for agent_id in all_agent_ids:
    agent = agents_dict[agent_id]
    print(f"  {agent.agent_id}: Total Reward = {agent.total_reward}")
    print(f"    Team Choice Est (A/B): {agent.team_choice_strategy['Team A']['value_est']:.2f}/{agent.team_choice_strategy['Team B']['value_est']:.2f}")
    print(f"    Signaling Est (A/B): {agent.signaling_strategy['Team A']['value_est']:.2f}/{agent.signaling_strategy['Team B']['value_est']:.2f}")
    for (sender_id, signal), data in agent.signal_interpretation.items():
        if sender_id != agent.agent_id:
            print(f"    Interpretation {sender_id} sent {signal}: {data['team_a_prob_est']:.2f}")

final_collective_reward = sum(agent.total_reward for agent in agents_dict.values())
print(f"Final Collective Reward: {final_collective_reward}")
